begin;
-- Add missing exam word help; preserve all existing reviewed meanings/profiles.
insert into public.englishsuccess_words(word,thai_gloss,word_profile,corpus_count,corpus_rank)
select word,thai_gloss,word_profile,0,null from jsonb_to_recordset($examwords$[{"word":"text","thai_gloss":"ข้อความ / บทอ่าน","word_profile":{"usage_frames":[{"word":"text","before":["the","my","your","this"],"after":["is","was"],"source":"teaching"},{"word":"texts","before":["the","my","your","these"],"after":["are","were"],"source":"teaching"}],"nouns":[{"singular":"text","plural":"texts","countability":"countable"}],"verbs":[],"before":[{"word":"the","count":3}],"after":[{"word":"only","count":2},{"word":"say","count":1}],"occurrences":3,"corpus_version":"exam-ch34-v1"}},{"word":"useful","thai_gloss":"มีประโยชน์","word_profile":{"usage_frames":[],"nouns":[],"verbs":[],"before":[{"word":"it","count":1}],"after":[{"word":"to","count":1}],"occurrences":1,"corpus_version":"exam-ch34-v1"}},{"word":"moved","thai_gloss":"ย้ายแล้ว / ย้ายเข้าไปอยู่แล้ว","word_profile":{"usage_frames":[],"nouns":[],"verbs":[{"base":"move","third":"moves","past":"moved","participle":"moved","ing":"moving"}],"before":[{"word":"they","count":2}],"after":[{"word":"in","count":2}],"occurrences":2,"corpus_version":"exam-ch34-v1"}},{"word":"money","thai_gloss":"เงิน","word_profile":{"usage_frames":[],"nouns":[{"singular":"money","plural":null,"countability":"uncountable"}],"verbs":[],"before":[{"word":"less","count":1}],"after":[],"occurrences":1,"corpus_version":"exam-ch34-v1"}},{"word":"arrive","thai_gloss":"มาถึง","word_profile":{"usage_frames":[],"nouns":[],"verbs":[{"base":"arrive","third":"arrives","past":"arrived","participle":"arrived","ing":"arriving"}],"before":[{"word":"train","count":1}],"after":[],"occurrences":1,"corpus_version":"exam-ch34-v1"}}]$examwords$::jsonb) as r(word text,thai_gloss text,word_profile jsonb)
on conflict(word) do update set thai_gloss=coalesce(englishsuccess_words.thai_gloss,excluded.thai_gloss),word_profile=coalesce(englishsuccess_words.word_profile,excluded.word_profile);
commit;
